// Compiles the production gamma table calculation with a host compiler
// and runs test/gamma/cases.cpp against it.
const assert = require('node:assert/strict');
const { it } = require('node:test');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const { spawnSync } = require('node:child_process');

// returns the complete definition that starts at signature, up to its closing brace
function extract(source, signature) {
  const start = source.indexOf(signature);
  assert.ok(start >= 0, 'Missing production definition ' + signature);
  const brace = source.indexOf('{', start);
  let depth = 0;
  for (let end = brace; end < source.length; end++) {
    if (source[end] === '{') depth++;
    if (source[end] === '}' && --depth === 0) return source.slice(start, end + 1);
  }
  throw new Error('Unclosed production definition ' + signature);
}

it('realtime packets do not recompute the gamma tables', t => {
  const compiler = process.env.CXX || 'g++';
  const probe = spawnSync(compiler, ['--version'], { encoding: 'utf8' });
  if (probe.error?.code === 'ENOENT') return t.skip('Host C++ compiler is unavailable');
  assert.equal(probe.status, 0, probe.stderr);
  const root = path.resolve(__dirname, '..');
  const read = name => fs.readFileSync(path.join(root, 'wled00', name), 'utf8');
  const colors = read('colors.cpp'), udp = read('udp.cpp');
  // a realtime override renders with gamma correction, so realtimeLock() must not select the unity table for it
  assert.match(extract(udp, 'void realtimeLock('), /arlsDisableGammaCorrection && md != REALTIME_MODE_INACTIVE && !realtimeOverride\)\s*\n\s*NeoGammaWLEDMethod::calcGammaTable\(1\.0f\)/);
  const source = fs.readFileSync(path.join(root, 'test/gamma/cases.cpp'), 'utf8')
    .replace('/* CALC_GAMMA_TABLE */', extract(colors, 'void NeoGammaWLEDMethod::calcGammaTable('));
  const temp = fs.mkdtempSync(path.join(os.tmpdir(), 'wled-gamma-'));
  try {
    const cpp = path.join(temp, 'gamma.cpp'), binary = path.join(temp, 'gamma-test');
    fs.writeFileSync(cpp, source);
    const build = spawnSync(compiler, ['-std=c++17', '-O0', '-Wall', '-Wextra', '-fsanitize=undefined', cpp, '-o', binary], { encoding: 'utf8' });
    assert.equal(build.status, 0, build.stdout + '\n' + build.stderr);
    const run = spawnSync(binary, [], { encoding: 'utf8' });
    t.diagnostic(run.stdout.trim().split('\n').at(-1));
    assert.equal(run.status, 0, run.stdout + '\n' + run.stderr);
  } finally {
    fs.rmSync(temp, { recursive: true, force: true });
  }
});
